/* Public PCA is raster-only. Interactive PCA stays inside the private browser workspace. */
const ReviewPCA=(()=>{
 'use strict';const requests=new Map(),images=new Map(),features=new WeakMap();
 const safe=s=>escapeHtml(String(s));
 function frame(){return '<div class="pca-evidence"><div class="full-wave-display-controls"><label>Axes<select data-pca-axes><option value="1">PC1 × PC2</option><option value="2">PC1 × PC3</option></select></label><span data-pca-count role="status">Loading PCA…</span></div><div class="pca-plot"><canvas data-pca-canvas aria-label="PCA projection of all selected cluster members"></canvas><canvas data-pca-selection hidden aria-label="Draw a polygon to select source-cluster spikes"></canvas></div><details class="evidence-details"><summary>PCA details</summary><p>Each point is a recorded waveform projected onto a shared, centered PCA basis for this recording. No amplitude normalization or separate per-cluster fit. Overlapping points can share a pixel; no spikes are sampled. Separation alone does not establish neuron identity.</p><p data-pca-variance></p></details></div>';}
 function readonly(c){return c.synthetic===false?frame():'<p>PCA requires real waveforms.</p>';}
 async function evidence(c){const key=c.dataset_id+'--'+c.state_sha256;if(!requests.has(key)){requests.set(key,fetch('/review-pca/'+encodeURIComponent(key)+'.json').then(async r=>{if(!r.ok)throw Error('PCA evidence unavailable');const d=await r.json();if(d.schema!=='review-pca-layers-v1'||d.dataset_id!==c.dataset_id||d.state_sha256!==c.state_sha256||d.mat_sha256!==c.mat_sha256||!d.all_members||d.sampled||d.normalized)throw Error('PCA state mismatch');return d;}).catch(e=>{requests.delete(key);throw e;}));while(requests.size>12)requests.delete(requests.keys().next().value);}return requests.get(key);}
 async function mask(v){if(!/^\/review-pca\/atoms\/[A-Za-z0-9_.-]+\.png$/.test(v.url)||!/^[a-f0-9]{64}$/.test(v.sha256))throw Error('Invalid PCA layer');if(!images.has(v.url)){images.set(v.url,fetch(v.url).then(async r=>{if(!r.ok)throw Error('PCA image unavailable');const bytes=await r.arrayBuffer();if(await CurationCore.digest(bytes)!==v.sha256)throw Error('PCA layer integrity mismatch');return new Blob([bytes],{type:'image/png'});}));while(images.size>64)images.delete(images.keys().next().value);}return images.get(v.url);}
 function axes(canvas,bounds,pc){const width=Math.max(280,Math.floor(canvas.parentElement.clientWidth||600)),height=350;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d'),box={l:68,t:28,w:width-90,h:height-79};ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.font='12px system-ui';ctx.lineWidth=1;ctx.fillStyle='#345168';for(let i=0;i<5;i++){const x=box.l+box.w*i/4,y=box.t+box.h*i/4;ctx.strokeStyle='#dde5ec';ctx.beginPath();ctx.moveTo(x,box.t);ctx.lineTo(x,box.t+box.h);ctx.moveTo(box.l,y);ctx.lineTo(box.l+box.w,y);ctx.stroke();ctx.textAlign='center';ctx.fillText(Number((bounds[0]+(bounds[1]-bounds[0])*i/4).toPrecision(3)),x,height-30);ctx.textAlign='right';ctx.fillText(Number((bounds[3]-(bounds[3]-bounds[2])*i/4).toPrecision(3)),box.l-7,y+4);}ctx.textAlign='center';ctx.fillText('PC1 (source units)',box.l+box.w/2,height-8);ctx.textAlign='left';ctx.fillText('PC'+(pc+1)+' (source units)',box.l,17);return {ctx,box};}
 function variance(host,d){host.querySelector('[data-pca-variance]').textContent='Fit: '+d.fit_n.toLocaleString()+' waveforms · explained variance '+d.variance.map((v,i)=>'PC'+(i+1)+' '+(v*100).toFixed(2)+'%').join(' · ');}
 async function attachReadonly(host,c){const panel=host.querySelector('.pca-evidence');if(!panel)return;const canvas=panel.querySelector('[data-pca-canvas]'),status=panel.querySelector('[data-pca-count]');let epoch=0;
  const paint=async()=>{const token=++epoch;canvas.dataset.complete='false';panel.dataset.ready='false';try{const d=await evidence(c),pc=Number(panel.querySelector('[data-pca-axes]').value),target=comparisonTarget(c),units=[sourceUnit(c),...(target?[c.units.find(u=>u.id===target)]:[])];variance(panel,d);const {ctx,box}=axes(canvas,d.bounds[pc-1],pc);let count=0;for(let k=0;k<units.length;k++){const u=units[k],population=d.units[u.cluster_id];if(!population||population.n_spikes!==u.spikes||population.atoms.reduce((n,i)=>n+(d.atoms[i]?.n_spikes||0),0)!==u.spikes)throw Error('PCA member mismatch');for(const id of population.atoms){const bitmap=await createImageBitmap(await mask(d.atoms[id].views[pc-1]));if(token!==epoch||!canvas.isConnected){bitmap.close();return;}const tint=document.createElement('canvas');tint.width=bitmap.width;tint.height=bitmap.height;const tx=tint.getContext('2d');tx.drawImage(bitmap,0,0);bitmap.close();tx.globalCompositeOperation='source-in';tx.fillStyle=FULL_WAVEFORM_COLORS[k];tx.fillRect(0,0,tint.width,tint.height);ctx.drawImage(tint,box.l,box.t,box.w,box.h);}count+=u.spikes;}status.innerHTML=units.map((u,i)=>'<span style="color:'+FULL_WAVEFORM_COLORS[i]+';font-weight:600">'+safe(u.title)+' · '+u.spikes.toLocaleString()+'</span>').join(' / ');canvas.dataset.complete='true';canvas.dataset.points=count;canvas.dataset.stateSha=c.state_sha256;panel.dataset.ready='true';}catch(e){status.textContent=e.message;panel.dataset.error=e.message;}};
  panel.querySelector('[data-pca-axes]').onchange=paint;let width=0,timer;const observer=new ResizeObserver(()=>{if(!canvas.isConnected){observer.disconnect();return;}const next=Math.round(canvas.parentElement.clientWidth);if(next!==width){width=next;clearTimeout(timer);timer=setTimeout(paint,80);}});observer.observe(canvas.parentElement);paint();
 }
 function privateFeatures(view){if(!features.has(view))features.set(view,new Promise((resolve,reject)=>view.features(v=>v.error?reject(Error(v.error)):resolve(v))));return features.get(view);}
 function working(){return frame()+'<div class="pca-selection-actions"><label><input type="checkbox" data-pca-lasso> Select source spikes</label><button class="button small" data-pca-clear>Clear selection</button><button class="button small" data-pca-split disabled>Preview selected split</button><span data-pca-selected role="status"></span></div>';}
 async function attachWorking(host,{view,input,state,groups,axisGroups=groups,source,onSplit,canSplit,selectOnLoad=false}){
  const panel=host.querySelector('.pca-evidence');if(!panel)return;const canvas=panel.querySelector('[data-pca-canvas]'),overlay=panel.querySelector('[data-pca-selection]'),status=panel.querySelector('[data-pca-count]'),selector=panel.querySelector('[data-pca-axes]'),enable=host.querySelector('[data-pca-lasso]'),button=host.querySelector('[data-pca-split]'),selectionStatus=host.querySelector('[data-pca-selected]');let data,selected=[],polygon=[],bounds,box,drag=false;
  enable.disabled=!canSplit;enable.checked=!!canSplit&&selectOnLoad;overlay.hidden=!enable.checked;enable.title=canSplit?'Draw an area; only the source cluster is selected.':'Select one cluster outside an operation preview to split.';
  const cid=row=>CurationCore.rowLabel(input,state,row),visible=new Map(groups.map((g,i)=>[g.id,g.color||FULL_WAVEFORM_COLORS[i]])),axisIds=new Set(axisGroups.map(g=>g.id));
  const clear=()=>{selected=[];polygon=[];overlay.getContext('2d').clearRect(0,0,overlay.width,overlay.height);button.disabled=true;selectionStatus.textContent=enable.checked?'Draw around part of Cluster '+source+'; leave at least one spike outside.':'';};
  function paint(){if(!data||!canvas.isConnected)return;clear();const pc=Number(selector.value),rows=[];bounds=[Infinity,-Infinity,Infinity,-Infinity];for(let r=0;r<input.data.n_spikes;r++)if(axisIds.has(cid(r))){if(visible.has(cid(r)))rows.push(r);const x=data.scores[r*3],y=data.scores[r*3+pc];bounds[0]=Math.min(bounds[0],x);bounds[1]=Math.max(bounds[1],x);bounds[2]=Math.min(bounds[2],y);bounds[3]=Math.max(bounds[3],y);}if(!rows.length){status.textContent='No selected members';return;}for(const k of [0,2]){const pad=Math.max((bounds[k+1]-bounds[k])*.04,1e-6);bounds[k]-=pad;bounds[k+1]+=pad;}const a=axes(canvas,bounds,pc);box=a.box;overlay.width=canvas.width;overlay.height=canvas.height;
   for(const [id,color] of visible){const bin=new Uint32Array(Math.ceil(box.w)*Math.ceil(box.h)),w=Math.ceil(box.w),h=Math.ceil(box.h);for(const row of rows)if(cid(row)===id){const x=Math.max(0,Math.min(w-1,Math.floor((data.scores[row*3]-bounds[0])/(bounds[1]-bounds[0])*w))),y=Math.max(0,Math.min(h-1,Math.floor((bounds[3]-data.scores[row*3+pc])/(bounds[3]-bounds[2])*h)));bin[y*w+x]++;}const layer=document.createElement('canvas');layer.width=w;layer.height=h;const tx=layer.getContext('2d'),pixels=tx.createImageData(w,h),rgb=color.match(/[0-9a-f]{2}/gi).map(x=>parseInt(x,16));for(let i=0;i<bin.length;i++)if(bin[i]){pixels.data[i*4]=rgb[0];pixels.data[i*4+1]=rgb[1];pixels.data[i*4+2]=rgb[2];pixels.data[i*4+3]=255*(1-Math.pow(.82,bin[i]));}tx.putImageData(pixels,0,0);a.ctx.drawImage(layer,box.l,box.t,box.w,box.h);}
   status.innerHTML=groups.map(g=>'<span style="color:'+g.color+';font-weight:600">Cluster '+g.id+' · '+g.n.toLocaleString()+'</span>').join(' / ');variance(panel,data);canvas.dataset.complete='true';canvas.dataset.points=rows.length;canvas.dataset.axisBounds=JSON.stringify(bounds);canvas.dataset.axisClusters=JSON.stringify(axisGroups.map(g=>g.id));panel.dataset.ready='true';}
  const position=e=>{const r=overlay.getBoundingClientRect();return [(e.clientX-r.left)*overlay.width/r.width,(e.clientY-r.top)*overlay.height/r.height];};
  function outline(){const ctx=overlay.getContext('2d');ctx.clearRect(0,0,overlay.width,overlay.height);if(!polygon.length)return;ctx.beginPath();ctx.moveTo(...polygon[0]);for(const p of polygon.slice(1))ctx.lineTo(...p);ctx.closePath();ctx.fillStyle='#00847b22';ctx.fill();ctx.strokeStyle='#00685f';ctx.lineWidth=2;ctx.stroke();}
  overlay.onpointerdown=e=>{if(!enable.checked||!data||!box)return;clear();drag=true;polygon=[position(e)];overlay.setPointerCapture(e.pointerId);};overlay.onpointermove=e=>{if(drag){polygon.push(position(e));outline();}};overlay.onpointerup=e=>{if(!drag)return;drag=false;polygon.push(position(e));outline();const pc=Number(selector.value);selected=[];let total=0;for(let row=0;row<input.data.n_spikes;row++)if(cid(row)===source){total++;const x=box.l+(data.scores[row*3]-bounds[0])/(bounds[1]-bounds[0])*box.w,y=box.t+(bounds[3]-data.scores[row*3+pc])/(bounds[3]-bounds[2])*box.h;if(polygon.length>=3&&SpikePCA.inside(x,y,polygon))selected.push(row);}button.disabled=!selected.length||selected.length===total;selectionStatus.textContent=selected.length.toLocaleString()+' / '+total.toLocaleString()+' source spikes selected';overlay.dataset.selected=selected.length;};
  enable.onchange=()=>{overlay.hidden=!enable.checked;clear();};host.querySelector('[data-pca-clear]').onclick=clear;button.onclick=()=>onSplit(selected.slice());selector.onchange=paint;
  let width=0,timer;const observer=new ResizeObserver(()=>{if(!canvas.isConnected){observer.disconnect();return;}const next=Math.round(canvas.parentElement.clientWidth);if(next!==width){width=next;clearTimeout(timer);timer=setTimeout(paint,80);}});observer.observe(canvas.parentElement);try{data=await privateFeatures(view);paint();}catch(e){status.textContent=e.message;}
 }
 return {readonly,attachReadonly,working,attachWorking,evidence};
})();
